func LoadPin(path string) (Pin, error) {
	var inputs map[string]jsontext.Value
	b, err := os.ReadFile(path)
	if err != nil {
		return Pin{}, err
	}
	if err = json.Unmarshal(b, &inputs); err != nil {
		return Pin{}, err
	}
	raw, ok := inputs["netbird"]
	if !ok {
		return Pin{}, errors.New("missing NetBird input pin")
	}
	return ValidatePinJSON(raw)
}

func ValidatePinJSON(raw []byte) (Pin, error) {
	var pin Pin
	keys, err := orderedKeys(raw)
	if err != nil {
		return pin, err
	}
	if !slices.Equal(keys, []string{"version", "archives", "enrollment_config"}) {
		return pin, errors.New("NetBird pin needs version, archives and enrollment_config")
	}
	if err = json.Unmarshal(raw, &pin, json.RejectUnknownMembers(true)); err != nil {
		return pin, err
	}
	var fields map[string]jsontext.Value
	if err = json.Unmarshal(raw, &fields); err != nil {
		return pin, err
	}
	keys, err = orderedKeys(fields["archives"])
	if err != nil {
		return pin, err
	}
	if !slices.Equal(keys, []string{"arm64", "amd64"}) {
		return pin, errors.New("NetBird archives must pin arm64 and amd64")
	}
	var archives map[string]jsontext.Value
	if err = json.Unmarshal(fields["archives"], &archives); err != nil {
		return pin, err
	}
	for _, arch := range []string{"arm64", "amd64"} {
		keys, err = orderedKeys(archives[arch])
		if err != nil {
			return pin, err
		}
		if !slices.Equal(keys, []string{"url", "bytes", "sha256", "binary_sha256"}) {
			return pin, fmt.Errorf("invalid NetBird %s archive source", arch)
		}
	}
	return pin, ValidatePin(pin)
}

func Verify(cfg Config, wire []byte) (network.Command, protocol.Envelope, error) {
	var step protocol.Envelope
	if err := protocol.DecodeStrict(wire, &step, 16<<10); err != nil {
		return network.Command{}, step, err
	}
	if err := protocol.VerifyEnvelope(step, protocol.EnvelopeScope{Region: cfg.Cell, Kind: "netbird.step", Actor: cfg.Node,
		OperationID: step.OperationID, Epoch: step.Epoch, Generation: step.Generation}, cfg.Controller, time.Now().UTC(), protocol.VerifyPolicy{MaxLifetime: StepLifetime, ClockSkew: time.Second}); err != nil {
		return network.Command{}, step, err
	}
	var command network.Command
	if err := json.Unmarshal(step.Payload, &command, json.RejectUnknownMembers(true)); err != nil {
		return command, step, err
	}
	if command.ID != step.OperationID || !entityid.Valid(command.Transaction) || command.ID != network.CommandID(command.Transaction, command.Action) || step.Epoch == 0 || command.Generation == 0 || command.Generation != step.Generation {
		return command, step, errors.New("invalid NetBird command binding")
	}
	if command.Action != "install" && command.Action != "confirm" && command.Action != "rollback" {
		return command, step, errors.New("invalid NetBird action")
	}
	if err := client.ValidatePin(command.Target.Pin); err != nil {
		return command, step, err
	}
	if err := command.Target.Enrollment.Validate(); err != nil {
		return command, step, err
	}
	return command, step, nil
}

func DecodeStrict(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, true)
}

func decode(data []byte, destination any, maxBytes int, rejectUnknown bool) error {
	if maxBytes == 0 {
		maxBytes = DefaultMaxJSONBytes
	}
	if maxBytes < 0 {
		return fmt.Errorf("%w: negative byte limit", ErrInvalidJSON)
	}
	if len(data) > maxBytes {
		return ErrJSONTooLarge
	}
	if !utf8.Valid(data) {
		return fmt.Errorf("%w: invalid UTF-8", ErrInvalidJSON)
	}
	if err := json.Unmarshal(data, destination,
		json.RejectUnknownMembers(rejectUnknown),
		jsontext.AllowDuplicateNames(false),
	); err != nil {
		return fmt.Errorf("decode protocol JSON: %w", err)
	}
	return nil
}

func SignEnvelope(
	payload []byte,
	scope EnvelopeScope,
	issuedAt time.Time,
	expiresAt time.Time,
	privateKey ed25519.PrivateKey,
) (Envelope, error) {
	if len(privateKey) != ed25519.PrivateKeySize {
		return Envelope{}, fmt.Errorf("%w: expected an Ed25519 private key", ErrInvalidEnvelope)
	}
	normalized, err := normalizeScope(scope)
	if err != nil {
		return Envelope{}, err
	}
	issuedAt = issuedAt.Round(0).UTC()
	expiresAt = expiresAt.Round(0).UTC()
	if !validProtocolTime(issuedAt) || !validProtocolTime(expiresAt) || !expiresAt.After(issuedAt) {
		return Envelope{}, fmt.Errorf("%w: issuedAt and expiresAt must form a valid UTC interval", ErrInvalidEnvelope)
	}
	compactPayload, err := compactPayload(payload)
	if err != nil {
		return Envelope{}, err
	}
	publicKey := privateKey.Public().(ed25519.PublicKey)
	keyID, err := KeyID(publicKey)
	if err != nil {
		return Envelope{}, err
	}
	envelope := Envelope{
		SchemaVersion: EnvelopeSchemaVersion,
		Region:        normalized.Region,
		Kind:          normalized.Kind,
		Actor:         normalized.Actor,
		Generation:    normalized.Generation,
		Epoch:         normalized.Epoch,
		OperationID:   normalized.OperationID,
		IssuedAt:      issuedAt,
		ExpiresAt:     expiresAt,
		KeyID:         keyID,
		Payload:       compactPayload,
	}
	material, err := signedMaterial(envelope)
	if err != nil {
		return Envelope{}, err
	}
	envelope.Signature = base64.RawURLEncoding.EncodeToString(ed25519.Sign(privateKey, material))
	return envelope, nil
}

func VerifyEnvelope(
	envelope Envelope,
	expected EnvelopeScope,
	publicKey ed25519.PublicKey,
	now time.Time,
	policy VerifyPolicy,
) error {
	if len(publicKey) != ed25519.PublicKeySize || policy.MaxLifetime <= 0 || policy.ClockSkew < 0 || !validProtocolTime(now) {
		return ErrInvalidPolicy
	}
	if envelope.SchemaVersion != EnvelopeSchemaVersion {
		return fmt.Errorf("%w: unsupported schema version", ErrInvalidEnvelope)
	}
	actualScope, err := normalizeScope(EnvelopeScope{
		Region: envelope.Region, Kind: envelope.Kind, Actor: envelope.Actor,
		OperationID: envelope.OperationID, Generation: envelope.Generation, Epoch: envelope.Epoch,
	})
	if err != nil {
		return err
	}
	expectedScope, err := normalizeScope(expected)
	if err != nil {
		return err
	}
	if actualScope != expectedScope {
		return ErrScopeMismatch
	}
	if !validProtocolTime(envelope.IssuedAt) || !validProtocolTime(envelope.ExpiresAt) ||
		!envelope.ExpiresAt.After(envelope.IssuedAt) ||
		envelope.ExpiresAt.Sub(envelope.IssuedAt) > policy.MaxLifetime {
		return fmt.Errorf("%w: invalid timestamp interval", ErrInvalidEnvelope)
	}
	issuedAt := envelope.IssuedAt.Round(0).UTC()
	expiresAt := envelope.ExpiresAt.Round(0).UTC()
	if issuedAt.Sub(now) > policy.ClockSkew {
		return ErrNotYetValid
	}
	if !now.Before(expiresAt) {
		return ErrExpired
	}
	expectedKeyID, err := KeyID(publicKey)
	if err != nil {
		return err
	}
	if envelope.KeyID != expectedKeyID {
		return ErrKeyMismatch
	}
	compact, err := compactPayload(envelope.Payload)
	if err != nil {
		return err
	}
	envelope.Region = actualScope.Region
	envelope.Kind = actualScope.Kind
	envelope.Actor = actualScope.Actor
	envelope.OperationID = actualScope.OperationID
	envelope.IssuedAt = issuedAt
	envelope.ExpiresAt = expiresAt
	envelope.Payload = compact
	material, err := signedMaterial(envelope)
	if err != nil {
		return err
	}
	signature, err := base64.RawURLEncoding.DecodeString(envelope.Signature)
	if err != nil || len(signature) != ed25519.SignatureSize || !ed25519.Verify(publicKey, material, signature) {
		return ErrBadSignature
	}
	return nil
}

func normalizeScope(scope EnvelopeScope) (EnvelopeScope, error) {
	region, err := CanonicalRegion(scope.Region)
	if err != nil || !validKind(scope.Kind) || !validIdentity(scope.Actor, 256) || !entityid.Valid(scope.OperationID) {
		return EnvelopeScope{}, ErrInvalidScope
	}
	scope.Region = region
	return scope, nil
}

func compactPayload(payload []byte) (jsontext.Value, error) {
	if len(payload) == 0 || len(payload) > MaxPayloadBytes {
		return nil, fmt.Errorf("%w: payload is empty or too large", ErrInvalidPayload)
	}
	value := jsontext.Value(payload).Clone()
	if err := value.Compact(
		jsontext.AllowDuplicateNames(false),
		jsontext.AllowInvalidUTF8(false),
	); err != nil {
		return nil, fmt.Errorf("%w: %v", ErrInvalidPayload, err)
	}
	if len(value) == 0 || value.Kind() != jsontext.Kind('{') {
		return nil, fmt.Errorf("%w: payload must be a JSON object", ErrInvalidPayload)
	}
	return value, nil
}

func signedMaterial(envelope Envelope) ([]byte, error) {
	payload, err := compactPayload(envelope.Payload)
	if err != nil {
		return nil, err
	}
	material := make([]byte, 0, len(envelopeDomain)+256+sha256.Size)
	material = append(material, envelopeDomain...)
	material = binary.BigEndian.AppendUint16(material, uint16(envelope.SchemaVersion))
	for _, value := range []string{
		envelope.Region,
		envelope.Kind,
		envelope.Actor,
		envelope.OperationID,
		envelope.KeyID,
		envelope.IssuedAt.UTC().Format(time.RFC3339Nano),
		envelope.ExpiresAt.UTC().Format(time.RFC3339Nano),
	} {
		material = appendString(material, value)
	}
	material = binary.BigEndian.AppendUint64(material, envelope.Generation)
	material = binary.BigEndian.AppendUint64(material, envelope.Epoch)
	payloadDigest := sha256.Sum256(payload)
	material = append(material, payloadDigest[:]...)
	return material, nil
}

func Parse(value string) (ulid.ULID, error) {
	id, err := ulid.ParseStrict(value)
	if err != nil || id == (ulid.ULID{}) || id.String() != value {
		return ulid.ULID{}, errors.New("entity ID must be a canonical uppercase ULID")
	}
	return id, nil
}

func Valid(value string) bool {
	_, err := Parse(value)
	return err == nil
}

func Derive(domain string, values ...string) string {
	h := sha256.New()
	for _, value := range append([]string{domain}, values...) {
		var size [8]byte
		binary.BigEndian.PutUint64(size[:], uint64(len(value)))
		h.Write(size[:])
		h.Write([]byte(value))
	}
	return ulid.MustNew(0, bytes.NewReader(h.Sum(nil)[:10])).String()
}

func CommandID(transaction, action string) string {
	return entityid.Derive("netbird-command", transaction, action)
}

func ValidatePin(p Pin) error {
	if !regexp.MustCompile(`^[0-9]+\.[0-9]+\.[0-9]+$`).MatchString(p.Version) {
		return errors.New("NetBird pin needs version, archives and enrollment_config")
	}
	for _, arch := range []string{"arm64", "amd64"} {
		a, _ := p.Archive(arch)
		expected := fmt.Sprintf("https://github.com/netbirdio/netbird/releases/download/v%s/netbird_%s_linux_%s.tar.gz", p.Version, p.Version, arch)
		if a.URL != expected {
			return fmt.Errorf("invalid NetBird %s archive source", arch)
		}
		if a.Bytes <= 0 || a.Bytes > MaxBinaryBytes {
			return fmt.Errorf("invalid NetBird %s archive size", arch)
		}
		if !SHA256Pattern.MatchString(a.SHA256) || !SHA256Pattern.MatchString(a.BinarySHA256) {
			return fmt.Errorf("invalid NetBird %s SHA-256", arch)
		}
	}
	return nil
}

func (cfg Config) Validate() error {
	_, err := cfg.normalized()
	return err
}

func (cfg Config) normalized() (Config, error) {
	if cfg.ManagementURL == "" {
		cfg.ManagementURL = DefaultManagementURL
	}
	if cfg.Region == "" {
		cfg.Region = DefaultRegion
	}
	manager, err := normalizeManagerURL(cfg.ManagementURL)
	if err != nil {
		return Config{}, err
	}
	cfg.ManagementURL = manager
	if cfg.ManagementIP != "" {
		ip, err := netip.ParseAddr(cfg.ManagementIP)
		if err != nil || !ip.IsPrivate() || ip.Zone() != "" || ip.Is4In6() {
			return Config{}, errors.New("NetBird management_ip must be a private IPv4 or IPv6 address")
		}
		cfg.ManagementIP = ip.String()
	}
	if !ValidSecretID(cfg.Region, cfg.SetupKeySecretID) {
		return Config{}, errors.New("NetBird setup_key_secret_id must identify an OCI Vault secret in the configured region")
	}
	if cfg.AdminPATSecretID != "" && !ValidSecretID(cfg.Region, cfg.AdminPATSecretID) {
		return Config{}, errors.New("NetBird admin_pat_secret_id must identify an OCI Vault secret in the configured region")
	}
	if err := ValidatePeerNames(cfg.PeerNames); err != nil {
		return Config{}, err
	}
	return cfg, nil
}

func Relay(ctx context.Context, cfg Config, wire []byte, fetch func(context.Context, string, io.Writer) error) error {
	command, _, err := Verify(cfg, wire)
	if err != nil {
		return err
	}
	spool, err := openSpool(cfg.Directory, true)
	if err != nil {
		return err
	}
	defer spool.close()
	if command.Action == "install" {
		pin, err := command.Target.Pin.Archive(runtime.GOARCH)
		if err != nil {
			return err
		}
		destination := "binary-" + pin.BinarySHA256
		if client.VerifyBinary(spool.path(destination), pin.BinarySHA256, runtime.GOARCH) != nil {
			file, temporary, err := spool.temporary()
			if err != nil {
				return err
			}
			defer spool.remove(temporary)
			err = fetch(ctx, pin.BinarySHA256, file)
			if err == nil {
				err = file.Sync()
			}
			err = errors.Join(err, file.Close())
			if err != nil {
				return err
			}
			if err := client.VerifyBinary(spool.path(temporary), pin.BinarySHA256, runtime.GOARCH); err != nil {
				return err
			}
			if err := spool.rename(temporary, destination); err != nil {
				return err
			}
		} else if err := spool.sync(destination, client.MaxBinaryBytes); err != nil {
			// Cached bytes may predate durability checks or an interrupted rename sync.
			return err
		}
	}
	// The transfer can exceed the signed step's short lifetime. The next
	// exchange supplies a fresh signature; it reuses the verified artifact.
	if _, _, err := Verify(cfg, wire); err != nil {
		return err
	}
	return spool.write("step.json", wire)
}

func (p Pin) Archive(architecture string) (Archive, error) {
	switch architecture {
	case "arm64":
		return p.Archives.Arm64, nil
	case "amd64":
		return p.Archives.AMD64, nil
	}
	return Archive{}, errors.New("unsupported architecture")
}

func VerifyBinary(path, expected, architecture string) error {
	return verifyBinaryLimit(path, expected, architecture, MaxBinaryBytes)
}

func verifyBinaryLimit(path, expected, architecture string, maximum int64) error {
	if !SHA256Pattern.MatchString(expected) {
		return errors.New("NetBird binary SHA-256 must be 64 lowercase hex characters")
	}
	f, e := openBoundedFileLimit(path, 64, maximum)
	if e != nil {
		return e
	}
	defer f.Close()
	var header [64]byte
	if _, e = io.ReadFull(f, header[:]); e != nil {
		return e
	}
	machine := uint16(183)
	if architecture == "amd64" {
		machine = 62
	} else if architecture != "arm64" {
		return errors.New("unsupported architecture")
	}
	if string(header[:7]) != "\x7fELF\x02\x01\x01" || (binary.LittleEndian.Uint16(header[16:]) != 2 && binary.LittleEndian.Uint16(header[16:]) != 3) || binary.LittleEndian.Uint16(header[18:]) != machine || binary.LittleEndian.Uint32(header[20:]) != 1 || binary.LittleEndian.Uint16(header[52:]) != 64 {
		return fmt.Errorf("NetBird binary must be an ELF64 little-endian %s executable", architecture)
	}
	h := sha256.New()
	h.Write(header[:])
	n, e := io.Copy(h, io.LimitReader(f, maximum+1-int64(len(header))))
	if e != nil {
		return e
	}
	if n+int64(len(header)) > maximum {
		return fmt.Errorf("NetBird binary exceeds %d bytes", maximum)
	}
	if hex.EncodeToString(h.Sum(nil)) != expected {
		return errors.New("NetBird binary bytes differ from the pinned SHA-256")
	}
	return nil
}

func openBoundedFileLimit(path string, minimum, maximum int64) (*os.File, error) {
	fd, err := syscall.Open(path, syscall.O_RDONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW|syscall.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), path)
	info, err := file.Stat()
	if err != nil || !info.Mode().IsRegular() || info.Size() < minimum || info.Size() > maximum {
		file.Close()
		return nil, fmt.Errorf("NetBird source must be a direct regular file within %d bytes", maximum)
	}
	return file, nil
}

func Write(directory, name string, wire []byte) error {
	if !spoolName(name) {
		return errors.New("invalid NetBird spool filename")
	}
	spool, err := openSpool(directory, true)
	if err != nil {
		return err
	}
	defer spool.close()
	return spool.write(name, wire)
}

func read(directory, name string, limit int64) ([]byte, error) {
	spool, err := openSpool(directory, false)
	if err != nil {
		return nil, err
	}
	defer spool.close()
	return spool.read(name, limit)
}

func openSpool(directory string, create bool) (*spool, error) {
	if !filepath.IsAbs(directory) || filepath.Clean(directory) != directory || directory == "/" {
		return nil, errors.New("invalid NetBird spool path")
	}
	fd, err := unix.Open("/", unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC, 0)
	if err != nil {
		return nil, err
	}
	for _, component := range strings.Split(strings.TrimPrefix(directory, "/"), "/") {
		next, err := unix.Openat(fd, component, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
		if errors.Is(err, unix.ENOENT) && create {
			var parent unix.Stat_t
			if err = unix.Fstat(fd, &parent); err != nil {
				unix.Close(fd)
				return nil, err
			}
			created := false
			if err = unix.Mkdirat(fd, component, 0700); err == nil || errors.Is(err, unix.EEXIST) {
				created = err == nil
				next, err = unix.Openat(fd, component, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)
			}
			if err == nil && created && os.Geteuid() == 0 {
				// Root-first startup must preserve the relay's inherited ownership.
				if err = unix.Fchown(next, int(parent.Uid), int(parent.Gid)); err != nil {
					unix.Close(next)
				}
			}
		}
		unix.Close(fd)
		if err != nil {
			return nil, err
		}
		fd = next
	}
	file := os.NewFile(uintptr(fd), "NetBird spool directory")
	info, err := file.Stat()
	if err != nil || !info.IsDir() || info.Mode().Perm()&0022 != 0 {
		file.Close()
		return nil, errors.New("unsafe NetBird spool directory")
	}
	return &spool{file}, nil
}

func (s *spool) temporary() (*os.File, string, error) {
	name := ".netbird-" + rand.Text()
	fd, err := unix.Openat(int(s.directory.Fd()), name, unix.O_WRONLY|unix.O_CREAT|unix.O_EXCL|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0600)
	if err != nil {
		return nil, "", err
	}
	return os.NewFile(uintptr(fd), "NetBird spool temporary"), name, nil
}

func (s *spool) rename(source, destination string) error {
	if !spoolName(source) || !spoolName(destination) {
		return errors.New("invalid NetBird spool filename")
	}
	fd := int(s.directory.Fd())
	if err := unix.Renameat(fd, source, fd, destination); err != nil {
		return err
	}
	return s.directory.Sync()
}

func (s *spool) write(name string, wire []byte) error {
	if !spoolName(name) {
		return errors.New("invalid NetBird spool filename")
	}
	file, temporary, err := s.temporary()
	if err != nil {
		return err
	}
	defer s.remove(temporary)
	if _, err = file.Write(wire); err == nil {
		if name == "status.json" || name == "result.json" {
			err = file.Chmod(0644)
		}
		if err == nil {
			err = file.Sync()
		}
	}
	err = errors.Join(err, file.Close())
	if err != nil {
		return err
	}
	return s.rename(temporary, name)
}

func (s *spool) read(name string, limit int64) ([]byte, error) {
	if !spoolName(name) || limit < 0 {
		return nil, errors.New("invalid NetBird spool read")
	}
	fd, err := unix.Openat(int(s.directory.Fd()), name, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW|unix.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	file := os.NewFile(uintptr(fd), "NetBird spool file")
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return nil, err
	}
	if !info.Mode().IsRegular() || info.Size() > limit || info.Mode().Perm()&0022 != 0 {
		return nil, errors.New("unsafe NetBird spool file")
	}
	wire, err := io.ReadAll(io.LimitReader(file, limit+1))
	if err != nil {
		return nil, err
	}
	if int64(len(wire)) > limit {
		return nil, errors.New("unsafe NetBird spool file")
	}
	return wire, nil
}

func (last ledger) accepts(command network.Command, step protocol.Envelope) bool {
	if step.Epoch < last.Epoch || step.Generation < last.Generation ||
		step.Generation == last.Generation && last.Transaction != "" && command.Transaction != last.Transaction {
		return false
	}
	if command.Transaction == last.Transaction && actionRank(command.Action) < actionRank(last.Action) {
		return false
	}
	if command.Transaction == last.Transaction && last.TargetHash != "" && network.Hash(command.Target) != last.TargetHash {
		return false
	}
	if command.Action == "confirm" && (last.InstalledTargetHash == "" || last.InstalledTargetHash != network.Hash(command.Target)) {
		return false
	}
	return command.ID != last.ActionID || last.Error != "" && command.Action != "install"
}

func stateDirectory(cfg Config) (string, error) {
	directory := cfg.StateDirectory
	if directory == "" {
		for _, part := range []string{cfg.Cell, cfg.Node} {
			if part == "" || part == "." || part == ".." || filepath.Base(part) != part {
				return "", errors.New("invalid NetBird worker identity")
			}
		}
		directory = filepath.Join(StateRoot, cfg.Cell, cfg.Node)
	}
	if !filepath.IsAbs(directory) || filepath.Clean(directory) != directory ||
		!filepath.IsAbs(cfg.Directory) || filepath.Clean(cfg.Directory) != cfg.Directory ||
		strings.HasPrefix(directory+"/", cfg.Directory+"/") || strings.HasPrefix(cfg.Directory+"/", directory+"/") {
		return "", errors.New("NetBird authority state must be separate from the relay spool")
	}
	current := string(filepath.Separator)
	for _, part := range strings.Split(strings.TrimPrefix(directory, "/"), "/") {
		current = filepath.Join(current, part)
		if err := os.Mkdir(current, 0700); err != nil && !errors.Is(err, os.ErrExist) {
			return "", err
		}
		info, err := os.Lstat(current)
		if err != nil || !info.IsDir() {
			return "", errors.New("NetBird authority state must not traverse symlinks")
		}
		stat, ok := info.Sys().(*syscall.Stat_t)
		if !ok || stat.Uid != uint32(os.Geteuid()) && stat.Uid != 0 ||
			info.Mode().Perm()&0022 != 0 && !(stat.Uid == 0 && info.Mode()&os.ModeSticky != 0) ||
			current == directory && (stat.Uid != uint32(os.Geteuid()) || info.Mode().Perm() != 0700) {
			return "", errors.New("NetBird authority state must be privately owned by the worker")
		}
	}
	return directory, nil
}

func loadLedger(directory string) (ledger, error) {
	fd, err := syscall.Open(filepath.Join(directory, "ledger.json"), syscall.O_RDONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW|syscall.O_NONBLOCK, 0)
	if errors.Is(err, os.ErrNotExist) {
		return ledger{}, nil
	}
	if err != nil {
		return ledger{}, err
	}
	file := os.NewFile(uintptr(fd), "NetBird authority ledger")
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return ledger{}, err
	}
	stat, ok := info.Sys().(*syscall.Stat_t)
	if !info.Mode().IsRegular() || info.Mode().Perm() != 0600 || info.Size() > 4096 || !ok || stat.Uid != uint32(os.Geteuid()) || stat.Nlink != 1 {
		return ledger{}, errors.New("unsafe NetBird authority ledger")
	}
	wire, err := io.ReadAll(io.LimitReader(file, 4097))
	if err != nil || len(wire) > 4096 {
		return ledger{}, errors.New("cannot read NetBird authority ledger")
	}
	var last ledger
	err = json.Unmarshal(wire, &last, json.RejectUnknownMembers(true))
	if err == nil && (last.ActionID != "" && !entityid.Valid(last.ActionID) ||
		last.Transaction != "" && !entityid.Valid(last.Transaction) ||
		last.PreviousManagedTransaction != "" && !entityid.Valid(last.PreviousManagedTransaction)) {
		err = errors.New("invalid NetBird ledger identity")
	}
	return last, err
}

func saveLedger(directory string, last ledger) error {
	wire, err := json.Marshal(last)
	if err != nil {
		return err
	}
	return Write(directory, "ledger.json", wire)
}

func applyStep(ctx context.Context, cfg Config, last *ledger, wire []byte, perform func(context.Context, network.Command) error) error {
	command, step, err := Verify(cfg, wire)
	if err != nil || !last.accepts(command, step) {
		return nil
	}
	if command.Transaction != last.Transaction {
		last.PreviousAppliedTargetHash = last.AppliedTargetHash
		last.InstalledTargetHash = ""
		last.InstallProgress, last.PreviousManagedTransaction = "unstarted", ""
	}
	// Authority is durable before effects, and is never read from the relay.
	last.Epoch, last.Generation = step.Epoch, step.Generation
	last.Transaction, last.Action = command.Transaction, command.Action
	last.TargetHash = network.Hash(command.Target)
	if err := saveLedger(cfg.StateDirectory, *last); err != nil {
		return err
	}
	actionErr := perform(ctx, command)
	last.ActionID, last.Error = command.ID, ""
	if actionErr != nil {
		last.Error = fmt.Sprint(actionErr)
	} else {
		switch command.Action {
		case "install":
			last.InstalledTargetHash = last.TargetHash
		case "confirm":
			last.AppliedTargetHash = last.InstalledTargetHash
		case "rollback":
			last.AppliedTargetHash = last.PreviousAppliedTargetHash
			last.InstalledTargetHash = ""
		}
	}
	if err := saveLedger(cfg.StateDirectory, *last); err != nil {
		return err
	}
	// This copy is diagnostic output only. A compromised relay may delete or
	// rewrite it without changing the worker's authority or target identity.
	result, _ := json.Marshal(last)
	if cfg.spool != nil {
		return cfg.spool.write("result.json", result)
	}
	return Write(cfg.Directory, "result.json", result)
}

func actionRank(action string) int {
	switch action {
	case "install":
		return 1
	case "confirm":
		return 2
	case "rollback":
		return 3
	}
	return 0
}

func Hash(target Target) string {
	wire, _ := json.Marshal(target, json.Deterministic(true))
	sum := sha256.Sum256(wire)
	return hex.EncodeToString(sum[:])
}

func executableMissing() bool {
	_, err := exec.LookPath("netbird")
	if !errors.Is(err, exec.ErrNotFound) {
		return false
	}
	// LookPath also returns ErrNotFound for a present, non-executable file.
	// Permissions and broken paths are failures, not missing-client bootstrap.
	for _, directory := range filepath.SplitList(os.Getenv("PATH")) {
		if _, err := os.Lstat(filepath.Join(directory, "netbird")); !errors.Is(err, os.ErrNotExist) {
			return false
		}
	}
	return true
}
